# activities.py: kid-friendly "What shall we explore?" page (CategoryScreen), a still Owl option, small Playful/StartScreen updates.
import base64, hashlib, sys
EXPECT = {'app/src/components/Playful.tsx': '627f9f5d548d0b3153ffa47c7ac94019', 'app/src/screens/StartScreen.tsx': '1f9ee808150ede4a439931a2d2f01857', 'app/src/screens/CategoryScreen.tsx': 'f983b605b4d11671ea93c1d59ffa7ff0', 'app/src/components/Owl.tsx': '25d01f13d694a70fd5e6d0d34d7cf831'}
for p, m in EXPECT.items():
    got = hashlib.md5(open(p, 'rb').read()).hexdigest()
    if got != m: sys.exit(f'{p} changed since staging ({got}); not applying')
PAYLOAD = {'app/src/components/Playful.tsx': '', 'app/src/screens/StartScreen.tsx': '', 'app/src/screens/CategoryScreen.tsx': '', 'app/src/components/Owl.tsx': ''}
WANT = {'app/src/components/Playful.tsx': '8ca35953f69da8bb73e2f37a2dedcd5e', 'app/src/screens/StartScreen.tsx': '80e184df97b186c6975ecb878207fb9d', 'app/src/screens/CategoryScreen.tsx': '5576b2c9b9097d3e8d1e0cb1d889d59d', 'app/src/components/Owl.tsx': '56b766f8509558c861f208fab9acfdbd'}
for p, b in PAYLOAD.items():
    open(p, 'wb').write(base64.b64decode(b))
    assert hashlib.md5(open(p, 'rb').read()).hexdigest() == WANT[p], p
    print('wrote', p, WANT[p])
